template <typename UnionPtrType>
PromoPartPtr PromoPart::Clone() const {
  switch (tag_) {
    case Tag::kImage:
      return NewImage(
          mojo::Clone(*data_.image));
    case Tag::kLink:
      return NewLink(
          mojo::Clone(*data_.link));
    case Tag::kText:
      return NewText(
          mojo::Clone(*data_.text));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, PromoPart>::value>::type*>
bool PromoPart::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kImage:
      return mojo::Equals(*(data_.image), *(other.data_.image));
    case Tag::kLink:
      return mojo::Equals(*(data_.link), *(other.data_.link));
    case Tag::kText:
      return mojo::Equals(*(data_.text), *(other.data_.text));
  }

  return false;
}
template <typename StructPtrType>
BackgroundCollectionPtr BackgroundCollection::Clone() const {
  return New(
      mojo::Clone(id),
      mojo::Clone(label),
      mojo::Clone(preview_image_url)
  );
}

template <typename T, BackgroundCollection::EnableIfSame<T>*>
bool BackgroundCollection::Equals(const T& other_struct) const {
  if (!mojo::Equals(this->id, other_struct.id))
    return false;
  if (!mojo::Equals(this->label, other_struct.label))
    return false;
  if (!mojo::Equals(this->preview_image_url, other_struct.preview_image_url))
    return false;
  return true;
}

template <typename T, BackgroundCollection::EnableIfSame<T>*>
bool operator<(const T& lhs, const T& rhs) {
  if (lhs.id < rhs.id)
    return true;
  if (rhs.id < lhs.id)
    return false;
  if (lhs.label < rhs.label)
    return true;
  if (rhs.label < lhs.label)
    return false;
  if (lhs.preview_image_url < rhs.preview_image_url)
    return true;
  if (rhs.preview_image_url < lhs.preview_image_url)
    return false;
  return false;
}
